}

#define NULL_NODE 0x7f7f7f7f

typedef struct TreeNode {
    int val;
    struct TreeNode *left;
    struct TreeNode *right;
} TreeNode;

bool insertIntoBST(TreeNode **root, int val) {
    if (*root == NULL) {
        *root = (TreeNode*)malloc(sizeof(TreeNode));
        if (*root == NULL) return false;
        (*root)->val = val;
        (*root)->left = NULL;
        (*root)->right = NULL;
        return true;
    }

    TreeNode *cur = *root;
    while (true) {
        if (val < cur->val) {
            if (cur->left == NULL) {
                cur->left = (TreeNode*)malloc(sizeof(TreeNode));
                if (cur->left == NULL) return false;
                cur->left->val = val;
                cur->left->left = NULL;
                cur->left->right = NULL;
                return true;
            }
            cur = cur->left;
        } else {
            if (cur->right == NULL) {
                cur->right = (TreeNode*)malloc(sizeof(TreeNode));
                if (cur->right == NULL) return false;
                cur->right->val = val;
                cur->right->left = NULL;
                cur->right->right = NULL;
                return true;
            }
            cur = cur->right;
        }
    }
}

static const char *p;

static void skipSpace(void) {
    while (*p && isspace((unsigned char)*p)) ++p;
}

static int readTokenValue(void) {
    skipSpace();
    if (strncmp(p, "null", 4) == 0) {
        p += 4;
        return NULL_NODE;
    }

    int sign = 1;
    if (*p == '-') {
        sign = -1;
        ++p;
    }
    int x = 0;
    while (*p >= '0' && *p <= '9') {
        x = x * 10 + (*p - '0');
        ++p;
    }
    return sign * x;
}

static TreeNode *buildTreeFromLine(void) {
    skipSpace();
    if (*p != '[') return NULL;
    ++p;
    skipSpace();
    if (*p == ']') { ++p; return NULL; }

    int rootVal = readTokenValue();
    if (rootVal == NULL_NODE) return NULL;

    TreeNode *root = (TreeNode*)malloc(sizeof(TreeNode));
    root->val = rootVal;
    root->left = root->right = NULL;

    TreeNode **queue = (TreeNode**)malloc(10001 * sizeof(TreeNode*));
    int head = 0, tail = 0;
    queue[tail++] = root;

    while (head < tail) {
        TreeNode *node = queue[head++];
        skipSpace();
        if (*p == ',') ++p;
        skipSpace();
        if (*p == ']') { ++p; break; }

        int leftVal = readTokenValue();
        if (leftVal != NULL_NODE) {
            node->left = (TreeNode*)malloc(sizeof(TreeNode));
            node->left->val = leftVal;
            node->left->left = node->left->right = NULL;
            queue[tail++] = node->left;
        }

        skipSpace();
        if (*p == ',') ++p;
        skipSpace();
        if (*p == ']') { ++p; break; }

        int rightVal = readTokenValue();
        if (rightVal != NULL_NODE) {
            node->right = (TreeNode*)malloc(sizeof(TreeNode));
            node->right->val = rightVal;
            node->right->left = node->right->right = NULL;
            queue[tail++] = node->right;
        }
    }

    free(queue);
    return root;
}

static void printTree(TreeNode *root) {
    if (root == NULL) {
        puts("[]");
        return;
    }

    TreeNode **queue = (TreeNode**)malloc(20001 * sizeof(TreeNode*));
    int head = 0, tail = 0;
    queue[tail++] = root;

    char **tokens = (char**)malloc(40001 * sizeof(char*));
