            snprintf(buf, sizeof(buf), "%d", node->val);
            tokens[count++] = dupstr(buf);
            queue[tail++] = node->left;
            queue[tail++] = node->right;
        }
    }

    while (count > 0 && strcmp(tokens[count - 1], "null") == 0) {
        free(tokens[--count]);
    }

    putchar('[');
    for (int i = 0; i < count; ++i) {
        if (i) putchar(',');
        fputs(tokens[i], stdout);
        free(tokens[i]);
    }
