    TreeNode **queue = (TreeNode**)malloc(10001 * sizeof(TreeNode*));
    int head = 0, tail = 0;
    queue[tail++] = root;
    while (head < tail) {
        TreeNode *node = queue[head++];
        if (node->left) queue[tail++] = node->left;
        if (node->right) queue[tail++] = node->right;
        free(node);
    }
    free(queue);
